import abc
import datetime
import os
import json
import re

from openpyxl import Workbook
from openpyxl.utils import get_column_letter

from taf.ul.bts_kpi_report_generator.generator.ExcelSetCell import ExcelSetCell
from taf.ul.bts_kpi_report_generator.generator.HTMLTable import HTMLTable
from taf.ul.bts_kpi_report_generator.generator.function_sorted import sorted_names_LNCEL


class GenerateInterface(object):
    __metaclass__ = abc.ABCMeta

    def __init__(self, path_dir, measurements, summary_measurement, summary_type_measurements, summary_start_time,
                 summary_interval, counters_name):
        """

        :param path_dir:
        :param measurements:
        :param summary_measurement:
        :param summary_type_measurements:
        :param summary_start_time:
        :param summary_interval:
        :param counters_name:
        """
        self._path_dir = path_dir
        self._measurements = measurements
        self._summary_measurement = summary_measurement
        self._summary_type_measurements = summary_type_measurements
        self._summary_start_time = summary_start_time
        self._summary_interval = summary_interval
        self.__counters_name = counters_name

    def generate(self):
        """

        :return:
        """
        self._generate_pmstats()
        if self._summary_measurement is not None:
            self._generate_summary()

    def _generate_pmstats(self):
        """

        :return:
        """
        for measurement in self._measurements:
            start_time = self._measurements[measurement].start_time
            end_time = self._measurements[measurement].start_time + datetime.timedelta(
                minutes=int(self._measurements[measurement].interval))
            name_file = 'PMStats_{}'.format(self._measurements[measurement].start_time.strftime('%Y%m%d_%H%M%S'))
            self._generate_file(self._measurements[measurement].type_measurements,
                                self._measurements[measurement].parameters, name_file, start_time, end_time)

    def _generate_summary(self):
        """

        :return:
        """
        start_time = self._summary_start_time
        end_time = start_time + datetime.timedelta(minutes=self._summary_interval)
        name_file = 'summary'
        self._generate_file(self._summary_type_measurements, self._summary_measurement, name_file, start_time, end_time)

    def _create_destination_dir(self, dir_name):
        """

        :param dir_name:
        :return:
        """
        if not os.path.exists(os.path.join(self._path_dir, dir_name)):
            os.mkdir(os.path.join(self._path_dir, dir_name))

    def _get_name_counter(self, counter):
        """

        :param counter:
        :return:
        """
        if counter in self.__counters_name:
            return self.__counters_name[counter]
        else:
            return 'NA'

    @staticmethod
    def _get_dn_type(parameters, type_measurements, type_measurement):
        """

        :param parameters:
        :param type_measurements:
        :param type_measurement:
        :return:
        """
        dn_type = set()
        for parameter in type_measurements[type_measurement]:
            for dn in parameters['[{}]'.format(parameter)]:
                dn_type.add(dn)
        return dn_type

    @abc.abstractmethod
    def _generate_file(self, type_measurements, parameters, name_file, start_time, end_time):
        pass


class GenerateHTML(GenerateInterface):
    def __init__(self, path_dir, measurements, summary_measurement, summary_type_measurements, summary_start_time,
                 summary_interval, counters_name):
        super(GenerateHTML, self).__init__(path_dir, measurements, summary_measurement, summary_type_measurements,
                                           summary_start_time, summary_interval, counters_name)

    def _generate_file(self, type_measurements, parameters, name_file, start_time, end_time):
        """

        :param type_measurements:
        :param parameters:
        :param name_file:
        :param start_time:
        :param end_time:
        :return:
        """
        self._create_destination_dir('html')
        name_file_with_extension = '{}.html'.format(name_file)
        file_html = open('{}'.format(os.path.join(self._path_dir, 'html', name_file_with_extension)), 'w+')
        file_create = HTMLTable(parameters)

        file_create.start_end_time(start_time, end_time)

        for type_measurement in sorted(type_measurements):
            file_create.add_to_table(type_measurement)
            dn_type = self._get_dn_type(parameters, type_measurements, type_measurement)
            file_create.add_dn_table(dn_type)

            for parameter in sorted(type_measurements[type_measurement]):
                file_create.add_rows(parameter, dn_type, self._get_name_counter(parameter))
            file_create.add_end_table_tag()

        file_create.add_end_table_tag()

        file_html.writelines(file_create.table)
        file_html.close()


class GenerateXLSX(GenerateInterface, ExcelSetCell):
    def __init__(self, path_dir, measurements, summary_measurement, summary_type_measurements, summary_start_time,
                 summary_interval, counters_name):
        super(GenerateXLSX, self).__init__(path_dir, measurements, summary_measurement, summary_type_measurements,
                                           summary_start_time, summary_interval, counters_name)
        self.__workbook = Workbook()
        self.__sheet = self.__workbook.active

    def _generate_file(self, type_measurements, parameters, name_file, start_time, end_time):
        """

        :param type_measurements:
        :param parameters:
        :param name_file:
        :param start_time:
        :param end_time:
        :return:
        """
        self._create_destination_dir('xlsx')

        self.__generate_header(name_file, start_time, end_time)

        row = 4
        for type_measurement in sorted(type_measurements):
            self.fill_cell(self.__sheet.cell(row=row, column=1), type_measurement, bold=True)

            row = row + 2
            dn_type = self._get_dn_type(parameters, type_measurements, type_measurement)

            self.fill_cell(self.__sheet.cell(row=row, column=1), 'ID', bold=True, horizontal='center',
                           vertical='center')
            self.fill_cell(self.__sheet.cell(row=row, column=2), 'NAME', bold=True, horizontal='center',
                           vertical='center')

            row = self.__generate_table(dn_type, parameters, row, type_measurement, type_measurements)
            row = row + 2

        max_column = self.__sheet.max_column
        for column in range(4, max_column + 1):
            self.__sheet.column_dimensions[get_column_letter(column)].width = 18

        name_file_with_extension = '{}.xlsx'.format(name_file)
        self.__workbook.save(os.path.join(self._path_dir, 'xlsx', name_file_with_extension))

    def __generate_header(self, name_file, start_time, end_time):
        """

        :param name_file:
        :param start_time:
        :param end_time:
        :return:
        """
        self.__sheet.title = name_file
        self.__sheet.column_dimensions['A'].width = 20
        self.__sheet.column_dimensions['B'].width = 75

        self.fill_cell(self.__sheet.cell(row=1, column=1), 'Start: {}'.format(start_time.strftime('%Y-%m-%d %H:%M:%S')),
                       bold=True, italic=True, size='14')
        self.fill_cell(self.__sheet.cell(row=2, column=1), 'End: {}'.format(end_time.strftime('%Y-%m-%d %H:%M:%S')),
                       bold=True, italic=True, size='14')

    def __generate_table(self, dn_type, parameters, row, type_measurement, type_measurements):
        """

        :param dn_type:
        :param parameters:
        :param row:
        :param type_measurement:
        :param type_measurements:
        :return:
        """
        column = 4
        for dn in sorted(dn_type, key=sorted_names_LNCEL(dn_type)):
            self.fill_cell(self.__sheet.cell(row=row, column=column), dn, bold=True, horizontal='center',
                           vertical='center', wrap_text=True)
            column = column + 1

        for parameter in sorted(type_measurements[type_measurement]):
            row = row + 1
            self.fill_cell(self.__sheet.cell(row=row, column=1), parameter)
            self.fill_cell(self.__sheet.cell(row=row, column=2), self._get_name_counter(parameter), horizontal='center',
                           wrap_text=True)
            column = 4
            for dn in sorted(dn_type, key=sorted_names_LNCEL(dn_type)):
                if dn in parameters['[{}]'.format(parameter)]:
                    self.fill_cell(self.__sheet.cell(row=row, column=column), parameters['[{}]'.format(parameter)][dn],
                                   horizontal='center')
                column = column + 1
        return row


class GenerateJSONCounters(GenerateInterface):
    def __init__(self, path_dir, measurements, summary_measurement, summary_type_measurements, summary_start_time,
                 summary_interval, counters_name, rise_pm_data='rise_pm_data.txt', json_file='counters.json'):
        super(GenerateJSONCounters, self).__init__(path_dir, measurements, summary_measurement,
                                                   summary_type_measurements, summary_start_time,
                                                   summary_interval, counters_name)

        self.rise_pm_data = rise_pm_data
        self.json_file = json_file

    def parse_pm_data(self):
        with open(os.path.join(self._path_dir, self.rise_pm_data)) as pm_data_file:
            pm_data = pm_data_file.read()
            new_pm_data = self.convert_perl_dict(pm_data)
            return new_pm_data

    def convert_perl_dict(self, pm_data):
        new_pm_data = re.sub(r'[\t|\n\s]+', ' ', pm_data)
        new_pm_data = re.sub(r'%COUNTERS = ', '', new_pm_data)
        new_pm_data = re.sub(r'=>', ':', new_pm_data)
        new_pm_data = re.sub(r'\(', '', new_pm_data)
        new_pm_data = re.sub(r'\);', '', new_pm_data)
        new_pm_data = re.sub(r'"', "'", new_pm_data)
        new_pm_data = re.sub(r"' : { '", '" : {"', new_pm_data)
        new_pm_data = re.sub(r"' : '", '" : "', new_pm_data)
        new_pm_data = re.sub(r"', '", '", "', new_pm_data)
        new_pm_data = re.sub(r"', }, '", '"}, "', new_pm_data)
        new_pm_data = re.sub(r"'", " ", new_pm_data)
        new_pm_data = re.sub(r' , },  %MEASUREMENTS =   ', '"}, "', new_pm_data)
        new_pm_data = '{"' + new_pm_data[2:-6] + '"}}'
        return new_pm_data

    def get_cell_name(self, dn):
        cell_name_regex = re.compile(r'LNCEL-[0-9]+')
        cell_name_match = cell_name_regex.search(dn)
        if cell_name_match:
            return cell_name_match.group()

    def _generate_file(self, type_measurements, parameters, name_file, start_time, end_time):
        """

        :param type_measurements:
        :param parameters:
        :param name_file:
        :param start_time:
        :param end_time:
        :return:
        """

        counters_dict = json.loads(self.parse_pm_data())
        counters_measurements = {}
        for type_measurement in sorted(type_measurements):

            for parameter in sorted(type_measurements[type_measurement]):
                dn_type = self._get_dn_type(parameters, type_measurements, type_measurement)
                cells_measurements = {}

                for dn in sorted(dn_type, key=sorted_names_LNCEL(dn_type)):
                    if dn in parameters['[{}]'.format(parameter)]:
                        cell_abbrev = self.get_cell_name(dn)
                        cells_measurements[cell_abbrev] = parameters['[{}]'.format(parameter)][dn]
                if parameter in counters_dict.keys():
                    counters_measurements[counters_dict[parameter]['abbrev']] = cells_measurements

        with open('{}'.format(os.path.join(self._path_dir, self.json_file)), 'w+') as file_name:
            json.dump(counters_measurements, file_name)
